import { createRuntime, type RuntimeOptions, type GenvrRuntime } from '@genvr/runtime';
import { WorldSession } from './session.js';
export { createRuntime, type GenvrRuntime, type RuntimeOptions } from '@genvr/runtime';
/** Browser-only subpath; the authoring core has no WebGL, DOM or React side effects. */
export async function previewWorld(session: WorldSession, container: HTMLElement,
  options: Omit<RuntimeOptions, 'container' | 'world' | 'terrainChunks' | 'onCommand'> = {}): Promise<GenvrRuntime> {
  return createRuntime({ ...options, container, world: session.world, terrainChunks: session.terrainChunks,
    fetchPackage: options.fetchPackage ?? (id => session.itemPackage(id)),
    // A viewer is read-only. All edits use the session tools/commands, followed by a fresh preview.
    editable: false, viewOnly: true,
  });
}
